package com.example.booknest.data.model

import com.squareup.moshi.JsonDataException
import com.squareup.moshi.Moshi
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Test

/**
 * Checks that the data classes match the real API JSON, using the same Moshi setup as the app
 * (adapters generated by @JsonClass). Uses fixed JSON strings, so no network is involved.
 */
class JsonParsingTest {

    private val moshi = Moshi.Builder().build()

    @Test
    fun `dashboard JSON from the API is parsed into books`() {
        val response = moshi.adapter(DashboardResponse::class.java).fromJson(DASHBOARD_JSON)

        assertNotNull(response)
        assertEquals(2, response!!.entityTotal)
        assertEquals(
            Book(
                title = "The Hobbit",
                author = "J.R.R. Tolkien",
                genre = "Fantasy",
                publicationYear = 1937,
                description = "A children's fantasy novel about the adventures of hobbit Bilbo Baggins, serving as a prelude to The Lord of the Rings."
            ),
            response.entities[1]
        )
        // Accented characters survive parsing
        assertEquals("Gabriel García Márquez", response.entities[0].author)
    }

    @Test
    fun `login response JSON is parsed into the keypass`() {
        val response = moshi.adapter(LoginResponse::class.java).fromJson("""{"keypass":"books"}""")

        assertEquals("books", response?.keypass)
    }

    @Test
    fun `login request is sent with the field names the API expects`() {
        val json = moshi.adapter(LoginRequest::class.java).toJson(LoginRequest("12345678", "Alice"))

        assertEquals("""{"username":"12345678","password":"Alice"}""", json)
    }

    @Test(expected = JsonDataException::class)
    fun `a book missing a required field is rejected`() {
        moshi.adapter(Book::class.java).fromJson("""{"title":"No author","genre":"Fiction"}""")
    }

    private companion object {
        val DASHBOARD_JSON = """
            {
              "entities": [
                {
                  "title": "One Hundred Years of Solitude",
                  "author": "Gabriel García Márquez",
                  "genre": "Magical Realism",
                  "publicationYear": 1967,
                  "description": "A multi-generational saga that tells the story of the Buendía family in the fictional town of Macondo."
                },
                {
                  "title": "The Hobbit",
                  "author": "J.R.R. Tolkien",
                  "genre": "Fantasy",
                  "publicationYear": 1937,
                  "description": "A children's fantasy novel about the adventures of hobbit Bilbo Baggins, serving as a prelude to The Lord of the Rings."
                }
              ],
              "entityTotal": 2
            }
        """.trimIndent()
    }
}
